const input = $input.first().json;
const p = input.body && typeof input.body === 'object' ? input.body : input;
const query = input.query && typeof input.query === 'object' ? input.query : {};
const trim = value => value == null ? '' : String(value).trim();
const textLength = value => Array.from(value).length;
const provider = trim(p.provider || query.provider);
const fields = {};
let formId = trim(p.form_id || query.form_id);
if (provider === 'contact-form-7') {
  Object.assign(fields, p.posted_data || {});
} else if (provider === 'wpforms-lite') {
  formId = formId || trim(p.form_data && p.form_data.id);
  if (!Array.isArray(p.fields)) throw new Error('WPForms Lite fields must be an array');
  for (const field of p.fields) {
    const key = trim(field && field.name);
    if (!key || Object.prototype.hasOwnProperty.call(fields, key)) throw new Error('WPForms Lite field name is missing or repeated');
    fields[key] = field.value;
  }
} else if (provider === 'forminator') {
  Object.assign(fields, p.data && typeof p.data === 'object' ? p.data : p);
  fields.event_id = fields.event_id || fields['hidden-1'];
  fields['full-name'] = fields['full-name'] || fields['name-1'];
  fields.email = fields.email || fields['email-1'];
  fields.message = fields.message || fields['textarea-1'];
} else if (provider === 'elementor-shaped-synthetic') {
  formId = formId || trim(p.form_id);
  for (const [key, field] of Object.entries(p.fields || {})) fields[key] = field && field.value;
} else {
  throw new Error('Unsupported provider; Elementor shape is synthetic compatibility coverage only');
}
const eventId = trim(fields.event_id || p.event_id);
const name = trim(fields['full-name'] || fields.name);
const email = trim(fields.email).toLowerCase();
const message = trim(fields.message);
if (!formId || !eventId) throw new Error('form_id and hidden event_id are required; entry_id is not a retry key');
if (!name) throw new Error('missing_name');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('invalid_email');
if (!message) throw new Error('missing_message');
if (textLength(name) > 200 || textLength(email) > 320 || textLength(message) > 4000) throw new Error('form field exceeds maximum size');
return [{ json: { provider, formId, eventId, name, email, message } }];
